window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[35]={"id":"035","numero":35,"titre":"Anomalies cycle menstruel - métrorragie","objectifs":[{"id":"35-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome prémenstruel","contenu":"<p>Le <span class=\"kw-def\">syndrome prémenstruel (SPM)</span> est un ensemble de manifestations <strong>bénignes</strong> pouvant intéresser de nombreux appareils, dont le seul point commun est leur <strong>caractère cyclique</strong> : apparition dans les <span class=\"kw-chiffre\">jours qui précèdent les règles</span>, disparition au début ou au cours des menstruations. Ils peuvent parfois être présents plus longtemps au cours du cycle (ex : 1ʳᵉ phase de la périménopause).</p>\n\n      <p><strong>Fréquence</strong> : il s'agit de <em>la gêne fonctionnelle la plus fréquemment signalée par les femmes</em> — <span class=\"kw-chiffre\">30 à 40 %</span> des femmes en âge de procréer.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rands signes classiques</h4>\n      <table >\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mastodynies</strong></td>\n            <td><span class=\"kw-clinique\">Douleurs mammaires</span> isolées, parfois seins réellement douloureux et tendus à l'examen clinique.</td>\n          </tr>\n          <tr>\n            <td><strong>Signes abdomino-pelviens</strong></td>\n            <td>\n              <strong>Ballonnement abdominal</strong> : congestion pelvienne, toujours gênant ;<br>\n              <strong>Troubles du transit</strong> : souvent associés ;<br>\n              <strong>Prise de poids transitoire</strong> : <span class=\"kw-chiffre\">3 à 4 kg maximum</span>, possible.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes neuropsychologiques</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Céphalées</span>, <span class=\"kw-clinique\">irritabilité</span>, <span class=\"kw-clinique\">anxiété</span>, <span class=\"kw-clinique\">syndrome dépressif</span> — intensité le plus souvent modérée.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Trouble dysphorique prémenstruel (DSM-5).</strong> Forme <span class=\"kw-alerte\">psychiatrique invalidante</span> du SPM : syndromes psychiatriques cycliques invalidants (isolés ou associés aux signes mammaires/abdomino-pelviens) avec <strong>retentissement sur la qualité de vie</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":1},{"id":"35-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie du syndrome prémenstruel","contenu":"<p>La <span class=\"kw-def\">physiopathologie</span> du SPM est <em>mal connue</em>. L'<span class=\"kw-def\">hyperœstrogénie relative</span> (et parfois même <strong>absolue</strong>) serait l'élément fondateur, induisant <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>rands mécanismes :</p>\n\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Conséquences cliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hyperperméabilité capillaire</strong></td>\n            <td>\n              <span class=\"kw-bio\">Œdème tissulaire interstitiel</span> dans certains organes :<br>\n              <strong>Seins</strong> : <span class=\"kw-clinique\">mastodynies</span> ;<br>\n              <strong>Cerveau</strong> : <span class=\"kw-clinique\">céphalées</span>, manifestations neuropsychologiques ;<br>\n              <strong>Viscères abdomino-pelviens</strong> : <span class=\"kw-clinique\">congestion pelvienne</span>, <span class=\"kw-clinique\">troubles du transit</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Perturbations de la transmission sérotoninergique</strong></td>\n            <td>Participe à la survenue des <span class=\"kw-clinique\">troubles neuropsychologiques</span> (irritabilité, syndrome dépressif, trouble dysphorique prémenstruel).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> C'est la rationalité du recours aux <span class=\"kw-ttt\">ISRS</span> dans les formes neuropsychologiques (effet sur la sérotonine) et aux <span class=\"kw-ttt\">progestatifs/œstroprogestatifs</span> dans les formes globales (<span class=\"kw-ttt\">réduction</span> du climat d'hyperœstrogénie relative).\n      </div>","frequence":0},{"id":"35-3","rang":"B","rubrique":"Étiologies","titre":"Connaître les situations physiologiques ou pathologiques pouvant favoriser la survenue ou l’aggravation d’un syndrome prémenstruel","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Facteurs favorisants</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Traitements hormonaux</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Contraceptifs microprogestatifs</span> (voie orale ou implant SC) ;<br>\n              <span class=\"kw-ttt\">DIU au lévonorgestrel</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Consommations excessives</strong> (mode de vie)</td>\n            <td>\n              <span class=\"kw-chiffre\">Caféine</span>, <span class=\"kw-chiffre\">nicotine</span>, <span class=\"kw-chiffre\">alcool</span>, <span class=\"kw-chiffre\">sucres rapides</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étapes de la vie génitale où le SPM est plus fréquent</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Adolescence</strong></td>\n            <td>Les <em>1ers cycles</em> sont volontiers <span class=\"kw-def\">dysovulatoires</span> → peut favoriser une <strong>hyperœstrogénie relative</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>1ʳᵉ phase de la périménopause +++</strong></td>\n            <td>\n              Tableau d'<span class=\"kw-alerte\">« hyperstimulation endogène » des ovaires</span> associant :<br>\n              <strong>Raccourcissement des cycles</strong> ;<br>\n              <strong>Règles plus abondantes</strong>, voire hémorragiques chez certaines patientes ;<br>\n              <strong>Climat d'hyperœstrogénie relative</strong> et même parfois <span class=\"kw-alerte\">absolue</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":0},{"id":"35-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition du cycle menstruel normal","contenu":"<p>Le <span class=\"kw-def\">cycle menstruel normal</span> est un cycle ovulatoire dont la durée varie typiquement entre <span class=\"kw-chiffre\">25 et 35 jours</span>, comptés du <strong>1ᵉʳ jour des règles</strong> au 1ᵉʳ jour des règles suivantes. Les <span class=\"kw-def\">menstruations normales</span> durent <span class=\"kw-chiffre\">3 à 6 jours</span> et correspondent à des pertes sanguines <span class=\"kw-chiffre\">&lt; 80 mL</span>. La présence de règles régulières signe le bon fonctionnement de l'<strong><span class=\"kw-def\">axe hypothalamo-hypophyso-ovarien</span></strong> et l'intégrité des voies génitales. Une <span class=\"kw-def\">anomalie du cycle menstruel</span> est <em>très souvent le fait d'un défaut d'ovulation</em> (anovulation ou dysovulation).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Anomalies du cycle — définitions à connaître verbatim</h4>\n      <table >\n        <thead><tr><th>Anomalie</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Aménorrhée</span></strong></td>\n            <td><span class=\"kw-def\">Absence de menstruations</span>, primaire ou secondaire.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Oligospanioménorrhée</span></strong></td>\n            <td>Cycles <span class=\"kw-chiffre\">&gt; 45 jours</span> avec en général des <strong>menstruations de faible abondance</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Cycles courts</strong></td>\n            <td>Cycles <span class=\"kw-chiffre\">&lt; 25 jours</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Cycles longs</strong></td>\n            <td>Cycles <span class=\"kw-chiffre\">entre 35 et 45 jours</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Spottings</span></strong></td>\n            <td>Pertes <strong>fréquentes de faibles quantités</strong> (gouttes) de sang d'origine génitale (quasi-quotidiennes).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir (définitions Collège CNGOF).</strong> Une <em>aménorrhée primaire</em> = absence de règles après <span class=\"kw-chiffre\">15 ans</span> en présence d'un développement normal des caractères sexuels secondaires (ou à<span class=\"kw-chiffre\"> 13 ans</span> en l'absence de tout signe de puberté). Une <em>aménorrhée secondaire</em> = arrêt des cycles <span class=\"kw-chiffre\">&gt; 3 mois</span> chez une femme antérieurement réglée. On parle d'<em>aménorrhée primosecondaire</em> en cas d'un unique épisode menstruel <span class=\"kw-def\">suivi</span> d'une aménorrhée. L'aménorrhée peut être <strong>physiologique</strong> : <span class=\"kw-ci\">grossesse</span>, allaitement, ménopause.\n      </div>","frequence":0},{"id":"35-5","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conséquences cliniques des troubles du cycle","contenu":"<p>Les conséquences cliniques varient selon le type de trouble et son ancienneté. Plusieurs grands axes sont à retenir :</p>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Gêne fonctionnelle</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Inconfort cyclique</span> (mastodynies, ballonnement, irritabilité — cf SPM) ;<br>\n              <span class=\"kw-clinique\">Retentissement sur la qualité de vie</span>, professionnel, relationnel ;<br>\n              <strong>Trouble dysphorique prémenstruel</strong> (DSM-5) dans les formes psychiatriques sévères.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fertilité</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Hypofertilité / infertilité</span> en cas d'anovulation chronique (SOPK, insuffisance ovarienne prématurée, hyperprolactinémie) — motif fréquent de consultation.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endomètre</strong></td>\n            <td>\n              <span class=\"kw-etio\">Hyperplasie endométriale</span> en cas d'imprégnation œstrogénique non opposée par la progestérone (anovulation prolongée) — risque à terme de <strong>cancer de l'endomètre</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragies</strong></td>\n            <td><span class=\"kw-clinique\">Ménorragies</span> sévères pouvant entraîner une <span class=\"kw-bio\">anémie ferriprive</span> ; spottings désagréables.</td>\n          </tr>\n          <tr>\n            <td><strong>Osseux et cardio-vasculaire</strong></td>\n            <td>Carence œstrogénique prolongée (IOP, aménorrhée hypothalamique sévère) → <span class=\"kw-alerte\">perte de densité osseuse</span> ± retentissement <span class=\"kw-bio\">CV</span> à long terme.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Note de source.</strong> Le Collège CNGOF (5ᵉ éd., 2021) ne consacre pas de section spécifique à cet objectif transversal. La synthèse ci-dessus consolide les conséquences mentionnées au fil des chapitres aménorrhée/IOP (carence œstrogénique → risque osseux) et hémorragies (ménorragies → anémie ferriprive ; anovulation prolongée → hyperplasie endométriale).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple · 42 — Aménorrhée</em></p>","frequence":0},{"id":"35-6","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de métrorragies","contenu":"<p>Les <span class=\"kw-clinique\">métrorragies</span> = saignements d'origine utérine survenant <strong>en dehors des règles</strong>. La démarche étiologique se structure <span class=\"kw-alerte\">par contexte clinique</span>, car l'arborescence change radicalement selon l'âge et le statut hormonal.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Femme en âge de procréer</h4>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> absolue.</strong> Toute métrorragie chez une femme en âge de procréer impose d'<span class=\"kw-alerte\">éliminer une grossesse en 1er</span> (<span class=\"kw-bio\">β-hCG plasmatique</span>) et de ne pas méconnaître une <span class=\"kw-alerte\">grossesse extra-utérine (GEU)</span> tant que la <span class=\"kw-ci\">grossesse</span> n'a pas été localisée par <span class=\"kw-imagerie\">échographie</span>.\n      </div>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Liées à une <span class=\"kw-ci\">grossesse</span></strong></td>\n            <td>\n              <span class=\"kw-etio\">GEU</span> +++ ; <span class=\"kw-etio\">fausse couche spontanée</span> ; <span class=\"kw-etio\">môle hydatiforme</span> ;<br>\n              <span class=\"kw-ci\">Grossesse</span> intra-utérine évolutive avec hémorragie de Hartmann (J20-J25, parfois) ;<br>\n              Pathologies du 2ᵉ-3ᵉ trimestre : <span class=\"kw-etio\">placenta praevia</span>, <span class=\"kw-etio\">hématome rétroplacentaire</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Organiques utérines/cervicales</strong></td>\n            <td>\n              <span class=\"kw-etio\">Polypes endométriaux</span> ou cervicaux ;<br>\n              <span class=\"kw-etio\">Fibromes utérins</span> (surtout sous-muqueux) ;<br>\n              <span class=\"kw-etio\">Adénomyose</span> ;<br>\n              <span class=\"kw-etio\">Endométrite</span> aiguë / chronique, <span class=\"kw-etio\">cervicite</span>, <span class=\"kw-etio\">IGH</span> ;<br>\n              <span class=\"kw-alerte\">Cancer du col utérin</span> (à évoquer +++ chez la femme jeune avec métrorragies provoquées post-coïtales) ; cancer de l'endomètre (plus rare avant <span class=\"kw-chiffre\">40 ans</span>).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Iatrogènes / contraception</strong></td>\n            <td>\n              <span class=\"kw-ttt\">COP</span> mal observée, en début de <span class=\"kw-bio\">plaquette</span>, oublis ;<br>\n              <span class=\"kw-ttt\">Microprogestatifs</span>, <span class=\"kw-ttt\">implant à l'étonogestrel</span>, <span class=\"kw-ttt\">DIU au lévonorgestrel</span> : <em>spottings fréquents les 1ers mois</em> ;<br>\n              <span class=\"kw-ttt\">DIU au cuivre</span> : règles plus abondantes ± spottings ;<br>\n              Contraception d'<span class=\"kw-alerte\">urgence</span> ; <strong>traitement hormonal substitutif</strong> de la ménopause.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fonctionnelles</strong></td>\n            <td><span class=\"kw-etio\">Anovulation / dysovulation</span> (SOPK, péri-ménarche, périménopause).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Périménopause</h4>\n      <p>Causes <strong>organiques</strong> les plus fréquentes : <span class=\"kw-etio\">fibromes</span>, <span class=\"kw-etio\">polypes</span>, <span class=\"kw-etio\">adénomyose</span>, <span class=\"kw-etio\">hyperplasie endométriale</span> ± atypique, <span class=\"kw-alerte\">cancer de l'endomètre</span> à dépister. Causes fonctionnelles : dysovulation périménopausique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Femme ménopausée</h4>\n      <div class=\"callout callout-danger\">\n        <strong>Toute métrorragie post-ménopausique = <span class=\"kw-alerte\">cancer de l'endomètre</span> jusqu'à preuve du contraire.</strong> Bilan obligatoire : <span class=\"kw-imagerie\">échographie</span> pelvienne endovaginale + hystéroscopie ± <span class=\"kw-bio\">biopsie</span> endométriale.\n      </div>\n      <p>Autres causes : <span class=\"kw-etio\">atrophie endométriale</span>, polypes, fibromes, cancer du col, sarcomes, THM mal équilibré, causes vaginales (atrophie).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification</span> mnémotechnique « PALM-COEIN » (FIGO)</h4>\n      <p>Cadre de référence des saignements utérins anormaux <strong>chez la femme non enceinte en âge de procréer</strong> : les <strong>PALM</strong> sont des causes <span class=\"kw-def\">structurelles</span> (imagerie/<span class=\"kw-bio\">histologie</span>), les <strong>COEIN</strong> sont <span class=\"kw-def\">non structurelles</span>.</p>\n      <table >\n        <thead><tr><th>PALM (structurelles)</th><th>COEIN (non structurelles)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>P</strong>olype ;<br>\n              <strong>A</strong>dénomyose ;<br>\n              <strong>L</strong>éiomyome (sous-muqueux et autre) ;<br>\n              <strong>M</strong>alignité et hyperplasie.\n            </td>\n            <td>\n              <strong>C</strong>oagulopathie ;<br>\n              <strong>O</strong>vulatoire (dysfonction) ;<br>\n              <strong>E</strong>ndométriale (cause) ;<br>\n              <strong>I</strong>atrogénie ;<br>\n              <strong>N</strong>on autrement précisée.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Métrorragies fonctionnelles (diagnostic d'élimination)</h4>\n      <p>Une fois <strong>toutes les étiologies organiques éliminées</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Métrorragies intermenstruelles au 14ᵉ jour</span> du cycle (ovulation) ;</li>\n        <li><span class=\"kw-etio\">Métrorragies prémenstruelles</span> par insuffisance lutéale ;</li>\n        <li><span class=\"kw-etio\">Métrorragies post-menstruelles</span> par insuffisance œstrogénique en début de cycle.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 24 — Complications de la grossesse · 300 — Tumeur col-corps utérin · 41 — Endométrisose · 36 — Contraception · 37 — IVG</em></p>","frequence":0},{"id":"35-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de ménorragies","contenu":"<p>Les <span class=\"kw-def\">ménorragies</span> = règles <strong>anormalement abondantes</strong> (&gt; <span class=\"kw-chiffre\">80 mL</span>) et/ou <strong>prolongées</strong> (&gt; <span class=\"kw-chiffre\">7 jours</span>). Quand elles s'associent à des saignements inter-menstruels, on parle de <span class=\"kw-def\">méno-métrorragies</span>. La quantification objective repose sur le <span class=\"kw-bio\">score de Higham</span> : on parle de ménorragies pour un <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">&gt; 100</span>. La démarche distingue <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rands cadres :</p>\n\n      <table >\n        <thead><tr><th>Cadre</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Organiques utérines</strong></td>\n            <td>\n              <span class=\"kw-etio\">Fibromes utérins</span> +++ (surtout <strong>sous-muqueux</strong> et <strong>interstitiels</strong>) ;<br>\n              <span class=\"kw-etio\">Adénomyose</span> ;<br>\n              <span class=\"kw-etio\">Polypes endométriaux</span> ;<br>\n              <span class=\"kw-etio\">Hyperplasie endométriale</span> ± atypique ;<br>\n              <span class=\"kw-alerte\">Cancer de l'endomètre</span> ;<br>\n              <span class=\"kw-etio\">Malformations utérines</span> ; <span class=\"kw-etio\">cicatrice de césarienne</span> (isthmocèle).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fonctionnelles</strong></td>\n            <td>\n              <span class=\"kw-etio\">Dysovulation / anovulation</span> chronique → endomètre proliféré non opposé par la progestérone ;<br>\n              Particulièrement fréquent en <strong>péri-ménarche</strong> et en <strong>périménopause</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Trouble de l'hémostase</strong></td>\n            <td>\n              <span class=\"kw-bio\">Maladie de Willebrand</span> +++ (à évoquer chez l'<strong>adolescente</strong> avec ménorragies dès la ménarche) ;<br>\n              <span class=\"kw-bio\">Thrombopénies</span> (PTI, hémopathies) ;<br>\n              <span class=\"kw-ttt\">Traitements anticoagulants</span> / <span class=\"kw-ttt\">antiagrégants</span> ;<br>\n              <span class=\"kw-ci\">Insuffisance hépatique</span> sévère, coagulopathies de consommation.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Iatrogènes contraception</strong></td>\n            <td>\n              <span class=\"kw-ttt\">DIU au cuivre</span> : majore l'abondance et la durée des règles ;<br>\n              <span class=\"kw-ttt\">Microprogestatifs</span> à l'inverse : peuvent provoquer spottings/aménorrhée plutôt que ménorragies.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endocriniennes</strong></td>\n            <td>\n              <span class=\"kw-etio\">Hypothyroïdie</span> (peut majorer les ménorragies) ;<br>\n              <span class=\"kw-etio\">SOPK</span> (rare ménorragie pure — plus souvent spaniomé/aménorrhée puis hémorragies de privation abondantes).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir — réflexe.</strong> Une adolescente avec ménorragies sévères dès la ménarche → <span class=\"kw-alerte\">évoquer un trouble de l'hémostase</span> (maladie de Willebrand surtout) en plus du bilan habituel (β-hCG, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-imagerie\">échographie</span>).\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Traitements généraux (quelle que soit l'étiologie).</strong> Selon le Collège CNGOF :\n        <ul>\n          <li><span class=\"kw-ttt\">Antifibrinolytique</span> : acide tranexamique (Exacyl®) ;</li>\n          <li><span class=\"kw-ttt\">Traitement martial</span> per os ou IV ;</li>\n          <li><strong>Transfusion</strong> si besoin.</li>\n        </ul>\n        Puis traitement <strong>étiologique</strong> : polype (résection hystéroscopique), adénomyose et myome (DIU au lévonorgestrel en 1ʳᵉ intention, <span class=\"kw-ttt\">chirurgie</span> sinon), hyperplasie sans atypie (progestatifs PO ou DIU LNG).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 300 — Tumeur col-corps utérin · 41 — Endométrisose · 36 — Contraception</em></p>","frequence":0},{"id":"35-8","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies d’aménorrhée primaire","contenu":"<p><span class=\"kw-def\">Aménorrhée primaire</span> = absence de ménarche après <span class=\"kw-chiffre\">15 ans</span> en présence d'un développement pubertaire normal, ou à <span class=\"kw-chiffre\">13 ans</span> en l'absence de tout signe de puberté. La démarche s'organise <strong>selon la présence ou non d'un développement pubertaire</strong> et selon les anomalies utéro-vaginales associées.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe Collège — 2 diagnostics en cas d'absence d'utérus à l'<span class=\"kw-imagerie\">échographie</span>.</strong> Bien différencier :\n        <ul>\n          <li><span class=\"kw-etio\">Agénésie müllérienne (MRKH)</span> : aplasie <span class=\"kw-etio\">congénitale</span> de l'utérus et des 2/3 supérieurs du vagin, caryotype <strong>46,XX</strong>, caractères sexuels secondaires normaux ;</li>\n          <li><span class=\"kw-etio\">Insensibilité complète aux androgènes (Morris)</span> : caryotype <strong>46,XY</strong>, phénotype féminin, testicules intra-abdominaux/inguinaux — <em>cause exceptionnelle</em>.</li>\n        </ul>\n      </div>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Anomalies anatomiques</strong> (filière génitale)</td>\n            <td>\n              <span class=\"kw-etio\">Imperforation hyménale</span> (hématocolpos, douleurs cycliques) ;<br>\n              <span class=\"kw-etio\">Malformations müllériennes</span> : agénésie / hypoplasie utérine, cloisons vaginales transverses ;<br>\n              <span class=\"kw-etio\">Syndrome de Mayer-Rokitansky-Küster-Hauser (MRKH)</span> : agénésie utéro-vaginale, ovaires fonctionnels, caryotype 46,XX ;<br>\n              <span class=\"kw-etio\">Syndrome d'insensibilité aux androgènes (Morris)</span> : phénotype féminin, caryotype 46,XY, testicules ectopiques.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anomalies chromosomiques / dysgénésies gonadiques</strong></td>\n            <td>\n              <span class=\"kw-etio\">Syndrome de Turner</span> (45,X et mosaïques) +++ : petite taille, dysgénésie gonadique, impubérisme, FSH élevée ;<br>\n              Dysgénésies gonadiques pures 46,XX ou 46,XY (<span class=\"kw-clinique\">syndrome de Swyer</span>) ;<br>\n              Trisomies, anomalies du chromosome X.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hypogonadisme hypogonadotrope</strong> (cause centrale)</td>\n            <td>\n              <span class=\"kw-etio\">Retard pubertaire constitutionnel</span> (diagnostic d'élimination) ;<br>\n              <span class=\"kw-etio\">Syndrome de Kallmann</span> (déficit GnRH + anosmie) ;<br>\n              <span class=\"kw-etio\">Hyperprolactinémie</span> (adénome hypophysaire, médicamenteuse) ;<br>\n              Pathologies hypothalamo-hypophysaires (craniopharyngiome, tumeurs sellaires, <span class=\"kw-clinique\">irradiation</span>) ;<br>\n              <span class=\"kw-etio\">Anorexie mentale</span>, dénutrition sévère, activité physique intense.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maladies endocriniennes / chroniques</strong></td>\n            <td>\n              <span class=\"kw-etio\">Hypothyroïdie</span> sévère ;<br>\n              <span class=\"kw-etio\">Hyperplasie congénitale des surrénales</span> (bloc en 21-hydroxylase) ;<br>\n              Maladies chroniques sévères (<span class=\"kw-def\">MICI</span>, <span class=\"kw-ci\">insuffisance rénale</span>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire</em></p>","frequence":0},{"id":"35-9","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies d’aménorrhée secondaire","contenu":"<p><span class=\"kw-def\">Aménorrhée secondaire</span> = arrêt des règles <span class=\"kw-chiffre\">≥ 3 mois consécutifs</span> chez une femme antérieurement réglée. La démarche étiologique s'appuie sur l'<strong>algorithme du bilan hormonal</strong> (cf obj-10) qui classe les causes en <strong>3 cadres</strong>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Réflexe 1ᵉʳ.</strong> Avant tout bilan, <span class=\"kw-alerte\">éliminer une grossesse</span> — la 1ʳᵉ cause d'aménorrhée secondaire chez une femme en âge de procréer reste la <span class=\"kw-ci\">grossesse</span>. <span class=\"kw-bio\">β-hCG plasmatique</span> systématique.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 1 — FSH/LH/œstradiol bas → cause centrale (hypothalamo-hypophysaire)</h4>\n      <table >\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hyperprolactinémie</strong> (prolactine ↑)</td>\n            <td>\n              <span class=\"kw-etio\">Adénome hypophysaire à prolactine (prolactinome)</span> +++ ;<br>\n              <strong>Hyperprolactinémie médicamenteuse</strong> (<span class=\"kw-ttt\">neuroleptiques</span>, antiémétiques, antidépresseurs, <span class=\"kw-ttt\">opiacés</span>) ;<br>\n              <span class=\"kw-etio\">Hypothyroïdie</span> périphérique (TRH ↑ → PRL ↑) ; <span class=\"kw-ci\">insuffisance rénale</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres causes centrales</strong> (prolactine normale)</td>\n            <td>\n              <span class=\"kw-etio\">Aménorrhée hypothalamique fonctionnelle</span> : <span class=\"kw-etio\">anorexie mentale</span>, dénutrition, sport intensif, stress chronique ;<br>\n              <span class=\"kw-etio\">Syndrome de Sheehan</span> (<span class=\"kw-clinique\">nécrose</span> hypophysaire du post-partum <span class=\"kw-etio\">hémorragique</span>) ;<br>\n              <span class=\"kw-etio\">Craniopharyngiome</span>, tumeurs sellaires, hypophysite, séquelles d'<span class=\"kw-clinique\">irradiation</span>/<span class=\"kw-ttt\">chirurgie</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 2 — FSH/(LH)/œstradiol normaux → cause utéro-vaginale ou SOPK</h4>\n      <table >\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>SOPK</strong> (syndrome des ovaires polykystiques) +++</td>\n            <td><span class=\"kw-chiffre\">5 à 10 %</span> des femmes en âge de procréer. <em>Cause la plus fréquente d'anovulation et d'aménorrhée secondaire normo-œstrogénique</em> ; test à la dydrogestérone positif. <strong><span class=\"kw-def\">Critères de</span> Rotterdam</strong> (2/3 suffisent, après exclusion des autres causes) : oligo/anovulation ; hyperandrogénie clinique/bio ; aspect échographique d'<span class=\"kw-radio\">ovaires polymicrokystiques</span> (<span class=\"kw-chiffre\">≥ 12 follicules de 2-9 mm</span> par ovaire et/ou volume ovarien <span class=\"kw-chiffre\">&gt; 10 mL</span>). Doser la <span class=\"kw-bio\">17-OH-progestérone</span> pour éliminer un bloc en 21-hydroxylase ; <span class=\"kw-bio\">AMH</span> élevée.</td>\n          </tr>\n          <tr>\n            <td><strong>Causes utéro-vaginales acquises</strong></td>\n            <td>\n              <span class=\"kw-etio\">Synéchies utérines</span> (syndrome d'Asherman) — post-<span class=\"kw-ttt\">curetage</span>, post-endométrite ;<br>\n              Sténoses cervicales post-conisation, post-chirurgicales.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre 3 — FSH/(LH) élevées + œstradiol bas → insuffisance ovarienne</h4>\n      <table >\n        <thead><tr><th>Sous-cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Insuffisance ovarienne prématurée (IOP)</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Aménorrhée &gt; 4 mois avant 40 ans + FSH &gt; 25 UI/l</span> (sur 2 dosages) + signes d'hypo-œstrogénie. Hypogonadisme <strong>hypergonadotrope</strong> ; ne répond pas au test aux progestatifs. Concerne <span class=\"kw-chiffre\">1 % des femmes &lt; 40 ans</span> (<span class=\"kw-chiffre\">0,1 %</span> avant <span class=\"kw-chiffre\">30 ans</span>). Étiologies : <em>idiopathique dans <span class=\"kw-chiffre\">80 %</span> des cas</em>, génétiques (Turner, prémutation X fragile FMR1, polyendocrinopathies), <span class=\"kw-etio\">iatrogène</span> (chimio, <span class=\"kw-ttt\">radiothérapie</span>, <span class=\"kw-ttt\">chirurgie</span> ovarienne), <span class=\"kw-etio\">auto-immune</span> (Addison). Faire caryotype + recherche prémutation FMR1 + bilan auto-immun.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ménopause</strong></td>\n            <td>Aménorrhée &gt;<span class=\"kw-chiffre\"> 12 mois</span> chez une femme &gt;<span class=\"kw-chiffre\"> 45-50 ans</span> en moyenne, avec FSH élevée et symptômes climatériques.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire · 253 — <span class=\"kw-etio\">Obésité</span> · 38 — Infertilité du couple</em></p>","frequence":0},{"id":"35-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies de spanioménorrhée","contenu":"<p>La <span class=\"kw-def\">spanioménorrhée</span> = cycles <span class=\"kw-chiffre\">&gt; 35 jours</span> (souvent &gt; 45 j = oligospanioménorrhée), c'est-à-dire des règles <strong>espacées et peu fréquentes</strong>. Elle correspond souvent à une <strong>forme fruste</strong> des étiologies d'aménorrhée secondaire — l'ovulation est irrégulière mais non totalement absente.</p>\n\n      <table >\n        <thead><tr><th>Cadre</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Endocrino-ovariennes</strong></td>\n            <td>\n              <span class=\"kw-etio\">SOPK</span> +++ — <em>cause de loin la plus fréquente</em>, sur <span class=\"kw-def\">terrain</span> d'hyperandrogénie ± insulinorésistance ;<br>\n              <span class=\"kw-etio\">Insuffisance ovarienne débutante</span> (forme infraclinique précoce de l'IOP) ;<br>\n              <span class=\"kw-etio\">Périménopause</span> : raccourcissement puis allongement progressif des cycles avant aménorrhée définitive.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hypothalamo-hypophysaires</strong></td>\n            <td>\n              <span class=\"kw-etio\">Hyperprolactinémie modérée</span> (médicamenteuse, microadénome) ;<br>\n              <span class=\"kw-etio\">Aménorrhée hypothalamique fonctionnelle</span> dans ses formes débutantes : <span class=\"kw-clinique\">anorexie</span> / dénutrition modérée, sport intensif, stress chronique.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endocriniennes générales</strong></td>\n            <td>\n              <span class=\"kw-etio\">Dysthyroïdies</span> (hypo- comme <span class=\"kw-def\">hyperthyroïdie</span>) ;<br>\n              <span class=\"kw-etio\">Hyperplasie congénitale des surrénales</span> à révélation tardive ;<br>\n              <span class=\"kw-etio\">Hypercorticisme</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Métaboliques</strong></td>\n            <td><span class=\"kw-etio\">Obésité</span> sévère (lien avec SOPK), <em>très bas poids</em> / dénutrition.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Devant une spanioménorrhée chez une femme jeune, le <span class=\"kw-etio\">SOPK</span> est l'hypothèse à éliminer en 1ʳᵉ intention (<span class=\"kw-imagerie\">échographie</span> pelvienne + bilan hormonal + testostérone totale + SHBG).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 253 — <span class=\"kw-etio\">Obésité</span> · 38 — Infertilité du couple</em></p>","frequence":0},{"id":"35-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan à réaliser pour le diagnostic des aménorrhées et des troubles du cycle","contenu":"<p>Le bilan d'une aménorrhée ou d'un trouble du cycle s'articule en 3 temps : <strong>1ʳᵉ intention</strong> (test à la dydrogestérone), <strong>bilan hormonal</strong> et <strong>imagerie</strong>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Préalable systématique.</strong> <span class=\"kw-bio\">β-hCG plasmatique</span> avant toute exploration — <span class=\"kw-alerte\">éliminer une grossesse</span>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Orientation à l'examen clinique (CAT Collège).</strong> Avant les dosages, rechercher :\n        <ul>\n          <li><span class=\"kw-clinique\">Signes d'hyperandrogénie</span> : hirsutisme (<span class=\"kw-bio\">score de Ferriman-Galwey &gt; 6</span>), acné sévère, alopécie androgénique du vertex → oriente vers un <span class=\"kw-etio\">SOPK</span> ;</li>\n          <li><span class=\"kw-clinique\">Galactorrhée</span> : association aménorrhée-galactorrhée très évocatrice d'<span class=\"kw-etio\">hyperprolactinémie</span> ;</li>\n          <li><span class=\"kw-clinique\">Signes de carence œstrogénique</span> : bouffées vasomotrices, sécheresse vaginale, dyspareunie, troubles du sommeil/psychiques, perte de libido ;</li>\n          <li><strong>Poids / IMC / fluctuations pondérales</strong>, <span class=\"kw-bio\">TCA</span>, érythrocyanose des extrémités + lanugo (signes d'hypométabolisme) → <span class=\"kw-etio\">aménorrhée hypothalamique fonctionnelle</span>.</li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1ʳᵉ intention — test aux progestatifs (dydrogestérone)</h4>\n      <p>1ᵉʳ test à réaliser devant toute aménorrhée <strong>secondaire</strong>, dans le but de déclencher une <em>hémorragie de privation</em>. Apport diagnostique limité (FP/FN importants), mais il oriente la suite du bilan.</p>\n\n      <table >\n        <thead><tr><th>Paramètre</th><th>Résultat / interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Modalités</strong></td>\n            <td>Administration d'un <span class=\"kw-ttt\">progestatif</span> (généralement <span class=\"kw-ttt\">dydrogestérone</span>) <em>per os</em>, <span class=\"kw-chiffre\">10 à 20 mg/j pendant 7-10 jours</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Test positif</strong></td>\n            <td>\n              <strong>Définition</strong> : survenue des menstruations dans les <span class=\"kw-chiffre\">5 jours</span> suivant l'arrêt du progestatif ;<br>\n              <strong>Interprétation</strong> : traduit une <strong>imprégnation œstrogénique de l'endomètre suffisante</strong> ;<br>\n              Si aménorrhée + test positif = <span class=\"kw-def\">aménorrhée par anovulation normo-œstrogénique</span> (ex. <span class=\"kw-etio\">SOPK</span>).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Test négatif</strong></td>\n            <td>\n              <strong>Définition</strong> : absence d'hémorragie de privation ;<br>\n              <strong>Interprétation</strong> : traduit une <strong>carence œstrogénique</strong> (pas de croissance endométriale). Causes :<br>\n              <span class=\"kw-etio\">Hypofonctionnement ovarien sévère</span> (atrophie endométriale par hypo-œstrogénie, indépendamment de sa cause) ;<br>\n              <span class=\"kw-etio\">Anomalie anatomique de la filière génitale</span> ;<br>\n              <strong><span class=\"kw-ci\">Grossesse</span></strong> (malgré l'imprégnation œstrogénique, la progestérone endogène est maintenue → pas d'hémorragie de privation).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Suites diagnostiques</strong></td>\n            <td>\n              Bilan hormonal + <span class=\"kw-imagerie\">échographie</span> pelvienne :<br>\n              Si test <strong>positif</strong> : examens complémentaires <span class=\"kw-chiffre\">3 jours</span> après le cycle déclenché ;<br>\n              Si test <strong>négatif</strong> (ou absence de test) : examens complémentaires peuvent être réalisés en aménorrhée.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Limite du test.</strong> Il n'est qu'une <em>indication diagnostique</em> — taux de <span class=\"kw-alerte\">faux positifs et faux négatifs important</span>. Ne dispense jamais d'un bilan hormonal complet.\n      </div>\n\n      <h4 style=\"margin:18px 0 6px;font-size:14px;color:#1f2937;\">Bilan hormonal — au moment des règles (<span class=\"kw-chiffre\">J2</span>-J5)</h4>\n      <p>Dosages : <span class=\"kw-bio\">β-hCG</span>, <span class=\"kw-bio\">FSH</span>, <span class=\"kw-bio\">œstradiol</span>, <span class=\"kw-bio\">prolactine</span> ± <span class=\"kw-bio\">LH</span>. Bilan à réaliser au moment des règles (<span class=\"kw-chiffre\">J2-J5 du cycle</span>) pour être interprété correctement, donc :</p>\n      <ul>\n        <li>Soit <strong>directement</strong> si le test à la dydrogestérone est négatif ;</li>\n        <li>Soit <span class=\"kw-chiffre\">3 jours après</span> un test à la dydrogestérone positif.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Orientation étiologique du bilan hormonal (algorithme Collège)</h4>\n      <table >\n        <thead><tr><th>Profil hormonal</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>FSH, LH, œstradiol bas</strong></td>\n            <td>\n              <span class=\"kw-etio\">Cause centrale</span> :<br>\n              <strong>Prolactine élevée</strong> → <span class=\"kw-etio\">hyperprolactinémie</span> (prolactinome, médicamenteuse) ;<br>\n              <strong>Prolactine normale</strong> → <span class=\"kw-etio\">autres causes centrales</span> (aménorrhée hypothalamique fonctionnelle, Sheehan, craniopharyngiome).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FSH, (LH), œstradiol normaux</strong></td>\n            <td>\n              <span class=\"kw-etio\">Cause utéro-vaginale</span> ou <span class=\"kw-etio\">SOPK</span> ;<br>\n              <strong>Apport de l'<span class=\"kw-imagerie\">échographie</span> pelvienne +++</strong> (ovaires polykystiques, synéchies, anomalie filière).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FSH, (LH) élevées + œstradiol bas</strong></td>\n            <td><span class=\"kw-alerte\">Insuffisance ovarienne prématurée</span> (avant <span class=\"kw-chiffre\">40 ans</span>) ou ménopause physiologique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Imagerie</h4>\n      <p><span class=\"kw-imagerie\">Échographie pelvienne</span> (sus-pubienne ± endovaginale) — recherche :</p>\n      <ul>\n        <li><strong>Anomalie de la filière génitale</strong> : agénésie utérine, synéchies, malformations müllériennes ;</li>\n        <li><strong>Pathologie ovarienne</strong> : aspect d'<span class=\"kw-etio\">ovaires polykystiques</span>, kystes, atrophie ovarienne (IOP).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>En 2ᵈ intention</strong> selon l'orientation : <span class=\"kw-imagerie\">IRM hypophysaire</span> (si hyperprolactinémie ou suspicion centrale), <span class=\"kw-bio\">caryotype</span> (Turner, dysgénésies), bilan <span class=\"kw-etio\">auto-immun</span> (IOP), <span class=\"kw-bio\">testostérone totale + SHBG</span> (SOPK, hyperandrogénie), <span class=\"kw-bio\">TSH</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée · 244 — Adénome hypophysaire · 38 — Infertilité du couple</em></p>","frequence":0},{"id":"35-12","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","contenu":"<p>Bilan structuré devant des saignements utérins : <strong>clinique</strong> → <strong>biologie</strong> → <strong>imagerie</strong> ± <strong><span class=\"kw-imagerie\">endoscopie</span></strong>. La <span class=\"kw-alerte\">β-hCG est systématique</span> chez toute femme en âge de procréer.</p>\n\n      <h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Examen clinique</h4>\n      <table >\n        <thead><tr><th>Temps</th><th>Éléments à recueillir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>\n              Caractéristiques du saignement (date début, abondance, durée, déclenchement, saignements intermenstruels <span class=\"kw-bio\">vs</span> règles abondantes) ;<br>\n              <strong>ATCD</strong> : gynécologiques, obstétricaux, FCV à jour, contraception, ATCD personnel/familial de cancer gynéco ;<br>\n              Signes associés : douleurs pelviennes, dyspareunie, leucorrhées, signes endocriniens.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen physique</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Examen au spéculum</span> +++ (origine du saignement : col, vagin, endo-utérin ? <span class=\"kw-clinique\">lésion</span> visible ?) ;<br>\n              <span class=\"kw-clinique\">Toucher vaginal</span> (taille/forme/mobilité utérus, masses annexielles) ;<br>\n              Examen général : <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">tachycardie</span>, signes de retentissement hémodynamique.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Biologie</h4>\n      <ul>\n        <li><span class=\"kw-bio\">β-hCG plasmatique</span> +++ chez toute femme en âge de procréer ;</li>\n        <li><span class=\"kw-bio\">NFS-plaquettes</span> et <span class=\"kw-bio\">bilan martial</span> : <span class=\"kw-bio\">ferritinémie + CRP</span> (un <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> peut masquer une hypoferritinémie) ;</li>\n        <li><span class=\"kw-bio\">TP/TCA</span> et <span class=\"kw-bio\">dosage du facteur Willebrand</span> (<em>indication large chez l'adolescente</em>), voire bilan d'hémostase complet si suspicion (contexte familial, <span class=\"kw-ttt\">anticoagulant</span>) ;</li>\n        <li><span class=\"kw-bio\">Groupe-Rh-RAI</span> si saignement abondant ;</li>\n        <li><span class=\"kw-bio\">FCV / test HPV</span> selon âge et <span class=\"kw-def\">dépistage</span> à jour.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Imagerie de 1ʳᵉ intention</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Échographie pelvienne sus-pubienne + endovaginale</span> +++ : <strong>épaisseur de l'endomètre</strong>, fibromes (nombre/localisation/taille), polypes, ovaires, masses annexielles, signes de GEU/<span class=\"kw-ci\">grossesse</span> intra-utérine.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2ᵈ intention</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hystéroscopie diagnostique</strong></td>\n            <td>\n              Suspicion de <span class=\"kw-etio\">pathologie endo-utérine</span> (polype, fibrome sous-muqueux, hyperplasie, cancer) ;<br>\n              Bilan systématique en cas de <span class=\"kw-alerte\">métrorragies post-ménopausiques</span> avec <span class=\"kw-radio\">endomètre</span> &gt; <span class=\"kw-chiffre\">4-5 mm</span> à l'écho.\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Biopsie</span> endométriale</strong></td>\n            <td>Indiquée chez <span class=\"kw-alerte\">toute patiente &gt; 45 ans</span> ou en cas de <span class=\"kw-def\">facteur de risque</span> de cancer de l'endomètre. Par pipelle de Cornier ou biopsies dirigées sous hystéroscopie — analyse histologique (hyperplasie, atypies, <span class=\"kw-alerte\">cancer de l'endomètre</span>). <em>⚠️ Faite à l'aveugle, ne peut éliminer avec certitude un cancer même si normale.</em></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> pelvienne</strong></td>\n            <td>Caractérisation de lésions complexes (fibromes nombreux, adénomyose, <span class=\"kw-def\">bilan préopératoire</span>, suspicion de cancer du corps utérin).</td>\n          </tr>\n          <tr>\n            <td><strong>Hystérosalpingographie</strong></td>\n            <td>Plus rare dans ce contexte — utile si suspicion de synéchies utérines.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Toute métrorragie post-ménopausique impose l'hystéroscopie + <span class=\"kw-bio\">biopsie</span> endométriale</strong> — c'est un <span class=\"kw-alerte\">cancer de l'endomètre jusqu'à preuve du contraire</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 300 — Tumeur col-corps utérin · 24 — Complications de la grossesse · 312 — Tumeur sein</em></p>","frequence":0},{"id":"35-13","rang":"A","rubrique":"Identifier une urgence","titre":"Reconnaître les situations d’urgence en cas de saignements utérins","contenu":"<p>Plusieurs scénarios imposent une <strong>prise en charge urgente</strong> devant des saignements utérins. À reconnaître au moindre signe d'appel.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Savoir évaluer les pertes sanguines & la gravité</h4>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Quantification</strong></td>\n            <td>Interrogatoire (garnitures, caillots, vêtements tachés), <span class=\"kw-bio\">score de Higham</span> (&gt; 100 = ménorragies), spéculum (saignement actif ?), <span class=\"kw-bio\">HemoCue® / NFS</span> (taux d'<span class=\"kw-bio\">hémoglobine</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Anémie mal tolérée</strong></td>\n            <td><span class=\"kw-clinique\">Tachycardie</span>, <span class=\"kw-clinique\">pâleur</span> cutanéo-muqueuse et conjonctivale, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">vertiges</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Signes de <span class=\"kw-alerte\">choc</span></strong></td>\n            <td><span class=\"kw-alerte\">Hypotension</span>, <span class=\"kw-clinique\">malaise</span>, <span class=\"kw-clinique\">sueurs</span>, extrémités froides, marbrures.</td>\n          </tr>\n          <tr>\n            <td><strong>Mise en condition</strong> (si <span class=\"kw-alerte\">choc</span> / anémie mal tolérée)</td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span>, <span class=\"kw-ttt\">2 VVP de bon calibre</span>, réchauffement, <span class=\"kw-ttt\">oxygénothérapie</span>, bilan bio (<span class=\"kw-bio\">NFS</span>, hémostase, groupe + rhésus 2 déterminations, bilan prétransfusionnel, β-hCG sauf <span class=\"kw-ci\">grossesse</span> IU connue).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>1. <span class=\"kw-ci\">Grossesse</span> extra-utérine (GEU) rompue.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Femme en âge de procréer</span> + <span class=\"kw-clinique\">métrorragies</span> ± <span class=\"kw-clinique\">douleur pelvienne brutale</span> + <span class=\"kw-clinique\">retard de règles</span> ;</li>\n          <li>Signes péritonéaux, hémopéritoine, scapulalgie (irritation phrénique) ;</li>\n          <li><span class=\"kw-alerte\">Choc hémorragique</span> possible — collapsus, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">pâleur</span> ;</li>\n          <li><strong>CAT</strong> : <span class=\"kw-bio\">β-hCG urgente</span> + <span class=\"kw-imagerie\">échographie pelvienne endovaginale</span> + <strong>bloc</strong> (cœlioscopie d'<span class=\"kw-alerte\">urgence</span>).</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>2. Hémorragie sévère / <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> (toutes causes).</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Tachycardie</span>, <span class=\"kw-clinique\">hypotension artérielle</span>, <span class=\"kw-clinique\">pâleur</span>, marbrures, <span class=\"kw-clinique\">sueurs</span>, troubles de la conscience ;</li>\n          <li>Saignement extériorisé abondant et persistant ;</li>\n          <li><strong>CAT</strong> : 2 VVP de gros calibre, <span class=\"kw-bio\">groupe-Rh-RAI + NFS + hémostase</span> en <span class=\"kw-alerte\">urgence</span>, <strong>remplissage</strong> par cristalloïdes, <strong>transfusion</strong> de CGR ± PFC/<span class=\"kw-bio\">plaquettes</span> si critères, geste d'<strong>hémostase</strong> (utérotoniques, tamponnement, embolisation, <span class=\"kw-ttt\">chirurgie</span> selon contexte).</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>3. Contexte du post-partum — hémorragie de la délivrance / atonie utérine.</strong>\n        <ul>\n          <li>Saignement &gt; <span class=\"kw-chiffre\">500 mL</span> (voie basse) / <span class=\"kw-chiffre\">1000 mL</span> (césarienne) dans les <span class=\"kw-chiffre\">24h</span> ;</li>\n          <li><span class=\"kw-clinique\">Globe utérin de sécurité absent</span>, utérus mou ;</li>\n          <li><strong>CAT</strong> : révision utérine, massage, <span class=\"kw-ttt\">oxytocine</span> puis <span class=\"kw-ttt\">sulprostone</span>, embolisation/<span class=\"kw-ttt\">chirurgie</span> d'hémostase si échec.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>4. Drapeaux diagnostiques à ne pas manquer (semi-urgents).</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Toute métrorragie post-ménopausique</span> = cancer de l'endomètre jusqu'à preuve du contraire — exploration en consultation rapide (<span class=\"kw-imagerie\">échographie</span> + hystéroscopie/<span class=\"kw-bio\">biopsie</span>) ;</li>\n          <li><span class=\"kw-alerte\">Métrorragies provoquées post-coïtales chez la femme jeune</span> → cancer du col utérin à éliminer (examen au spéculum, FCV, <span class=\"kw-bio\">biopsie</span> cervicale dirigée si <span class=\"kw-clinique\">lésion</span>) ;</li>\n          <li><span class=\"kw-alerte\">Anémie chronique mal tolérée</span> (<span class=\"kw-clinique\">asthénie</span> majeure, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">angor</span>) sur ménorragies prolongées.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 24 — Complications de la grossesse</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>GEU rompue <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale absolue</span></strong></p><p><span class=\"kw-bio\">β-hCG urgente</span> + <span class=\"kw-imagerie\">échographie endovaginale</span> → <span class=\"kw-ttt\">cœlioscopie d'hémostase</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li><span class=\"kw-clinique\">Métrorragies</span> + <span class=\"kw-clinique\">douleur pelvienne brutale</span> + <span class=\"kw-clinique\">retard de règles</span> chez une femme en âge de procréer</li><li>Signes péritonéaux, <span class=\"kw-clinique\">scapulalgie</span> (irritation phrénique), <span class=\"kw-alerte\">hémopéritoine</span></li><li><span class=\"kw-alerte\">Choc hémorragique</span> possible : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">pâleur</span></li></ul><p><strong>Hémorragie sévère / <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> <span class=\"q\">— toutes causes</span></strong></p><p><span class=\"kw-ttt\">2 VVP de gros calibre</span> · remplissage cristalloïdes · <span class=\"kw-bio\">groupe-Rh-RAI + NFS + hémostase</span> · <span class=\"kw-ttt\">transfusion de CGR</span> ± PFC/<span class=\"kw-bio\">plaquettes</span> si critères · geste d'hémostase</p><ul><li><span class=\"kw-alerte\">Hypotension</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">pâleur</span>, marbrures, <span class=\"kw-clinique\">sueurs</span>, troubles de la conscience</li><li>Saignement extériorisé <strong>abondant et persistant</strong></li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Urgence</span> immédiate (<span class=\"kw-alerte\">hospitalisation</span>) :</strong> <span class=\"kw-alerte\">GEU rompue</span>, <span class=\"kw-alerte\">choc hémorragique</span>, <span class=\"kw-clinique\">anémie mal tolérée</span> (<span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">malaise</span>).<br><strong>Consultation rapide (&lt;<span class=\"kw-chiffre\"> 72 h</span>) :</strong> <span class=\"kw-alerte\">métrorragie post-ménopausique</span> (cancer de l'endomètre jusqu'à preuve du contraire) · <span class=\"kw-alerte\">métrorragie post-coïtale</span> répétée (cancer du col).<br><strong>Ambulatoire :</strong> métrorragies isolées sans <span class=\"kw-alerte\">signe de gravité</span> ni contexte à risque — bilan en consultation programmée.</p>","redflags":"<ul><li><span class=\"kw-alerte\">GEU</span> — toute métrorragie + <span class=\"kw-clinique\">retard de règles</span> chez une femme en âge de procréer : <span class=\"kw-bio\">β-hCG</span> systématique, GEU à éliminer en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-alerte\">Métrorragie post-ménopausique</span> = <span class=\"kw-etio\">cancer de l'endomètre</span> jusqu'à preuve du contraire (<span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-imagerie\">hystéroscopie</span> + <span class=\"kw-bio\">biopsie</span> endométriale)</li><li><span class=\"kw-alerte\">Métrorragies provoquées post-coïtales</span> chez la femme jeune → <span class=\"kw-etio\">cancer du col utérin</span> à éliminer (examen au spéculum + <span class=\"kw-bio\">FCV</span> + <span class=\"kw-bio\">biopsie cervicale</span> dirigée si <span class=\"kw-clinique\">lésion</span> visible)</li><li><span class=\"kw-alerte\">Choc hémorragique</span> : <span class=\"kw-clinique\">hypotension</span> · <span class=\"kw-clinique\">tachycardie</span> · marbrures · troubles de la conscience</li><li><span class=\"kw-alerte\">Anémie chronique mal tolérée</span> (<span class=\"kw-clinique\">asthénie</span> majeure, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">angor</span>) sur ménorragies prolongées</li></ul>","principes":"<p>Démarche en <strong>2 temps</strong> : éliminer d'abord une <span class=\"kw-alerte\">urgence vitale</span> (<span class=\"kw-alerte\">GEU</span>, <span class=\"kw-alerte\">choc</span>), puis enquête étiologique (<span class=\"kw-bio\">β-hCG</span> · <span class=\"kw-imagerie\">échographie</span> · <span class=\"kw-imagerie\">hystéroscopie</span> selon contexte).</p><p><strong>Traitements généraux des saignements utérins</strong></p><p>puis traitement <strong>étiologique</strong> selon la cause identifiée</p><ul><li><span class=\"kw-ttt\">Acide tranexamique</span> (Exacyl®) — antifibrinolytique, quel que soit le mécanisme</li><li><span class=\"kw-ttt\">Traitement martial</span> per os ou IV — corriger l'<span class=\"kw-bio\">anémie ferriprive</span></li><li><span class=\"kw-ttt\">Transfusion de CGR</span> si critères hémodynamiques ou <span class=\"kw-bio\">Hb</span> basse mal tolérée</li></ul><p><strong>Traitement étiologique — grandes lignes</strong></p><ul><li><span class=\"kw-etio\">Polype</span> → résection hystéroscopique</li><li><span class=\"kw-etio\">Fibrome sous-muqueux / adénomyose</span> → <span class=\"kw-ttt\">DIU au lévonorgestrel</span> en 1ʳᵉ intention, <span class=\"kw-ttt\">chirurgie</span> sinon</li><li><span class=\"kw-etio\">Hyperplasie endométriale sans atypie</span> → <span class=\"kw-ttt\">progestatifs PO</span> ou <span class=\"kw-ttt\">DIU LNG</span></li><li><span class=\"kw-etio\">Cause iatrogène (DIU cuivre, microprogestatif)</span> → <span class=\"kw-def\">réévaluation</span> contraception</li><li><span class=\"kw-ci\">Cancer de l'endomètre / du col</span> → orientation oncologique urgente</li></ul><p><strong>Cas particulier — adolescente avec ménorragies sévères</strong></p><ul><li>Évoquer un <span class=\"kw-etio\">trouble de l'hémostase</span> en plus du bilan habituel</li><li><span class=\"kw-etio\">Maladie de Willebrand</span> +++ : <span class=\"kw-bio\">facteur Willebrand</span> + <span class=\"kw-bio\">TP/TCA</span> systématiques si ménorragies dès la ménarche</li></ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Métrorragies — quel contexte ? — β-hCG systématique chez toute femme en âge de procréer","detail":"<h4>CAT — métrorragies / saignements utérins anormaux — Démarche diagnostique : éliminer une <span class=\"kw-alerte\">urgence</span> (GEU, hémorragie), puis orienter par contexte</h4>","branches":[{"to":"q-grossesse","label":"Femme en âge de procréer","color":"amber"},{"to":"t-post-menopause","label":"Femme ménopausée","color":"red"}]},{"id":"q-grossesse","kind":"decision","label":"β-hCG positive ? — Résultat plasmatique quantitatif — obtenir avant toute imagerie","branches":[{"to":"q-localisation","label":"Oui — grossesse non encore localisée","color":"red"},{"to":"q-palm-coein","label":"Non — β-hCG négative","color":"blue"}]},{"id":"q-localisation","kind":"decision","label":"Localisation échographique ? — Échographie pelvienne endovaginale en urgence","branches":[{"to":"t-geu","label":"Masse latéro-utérine · hémopéritoine · pas de sac intra-utérin","color":"red"},{"to":"t-fcs","label":"Sac intra-utérin visible · β-hCG en baisse / sac vide évolutif","color":"amber"}]},{"id":"t-geu","kind":"terminal","label":"GEU (grossesse extra-utérine)","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Métrorragies</span> ± <span class=\"kw-clinique\">douleur pelvienne</span> + <span class=\"kw-clinique\">retard de règles</span></li><li><span class=\"kw-alerte\">Choc hémorragique</span> si <span class=\"kw-alerte\">rupture</span> : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">scapulalgie</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">β-hCG</span> positive · <span class=\"kw-imagerie\">échographie endovaginale</span> : <span class=\"kw-clinique\">masse</span> latéro-utérine ± <span class=\"kw-alerte\">hémopéritoine</span>, absence de sac intra-utérin</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Cœlioscopie d'hémostase</span> en <span class=\"kw-alerte\">urgence</span> (forme rompue) ou <span class=\"kw-ttt\">méthotrexate</span> selon critères (forme non rompue)</li></ul><h4>Renvoi</h4><ul><li>Item 25 (<span class=\"kw-ci\">Grossesse</span> extra-utérine)</li></ul>"},{"id":"t-fcs","kind":"terminal","label":"FCS / grossesse intra-utérine","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Fausse couche spontanée (FCS)</span> : sac intra-utérin ± embryon sans activité cardiaque</li><li><span class=\"kw-etio\">Grossesse intra-utérine évolutive</span> avec métrorragies de Hartmann (J20-J25)</li></ul><h4>CAT</h4><ul><li>Confirmation échographique · <span class=\"kw-def\">surveillance</span> ou aspiration selon terme et contexte · <span class=\"kw-bio\">groupe-Rh-RAI</span></li></ul><h4>Renvoi</h4><ul><li>Item 24 (Complications de la <span class=\"kw-ci\">grossesse</span>)</li></ul>"},{"id":"q-palm-coein","kind":"decision","label":"Origine des saignements — PALM-COEIN ? — Échographie pelvienne sus-pubienne + endovaginale · examen au spéculum","branches":[{"to":"t-palm","label":"Anomalie structurelle à l'échographie (polype, fibrome, adénomyose, hyperplasie / malignité)","color":"amber"},{"to":"t-coein","label":"Cause non structurelle (coagulopathie, dysovulation, iatrogène, endométriale)","color":"green"}]},{"id":"t-palm","kind":"terminal","label":"Cause organique PALM","color":"amber","detail":"<h4>Étiologies PALM</h4><ul><li><span class=\"kw-etio\">Polype</span> endométrial ou cervical</li><li><span class=\"kw-etio\">Adénomyose</span></li><li><span class=\"kw-etio\">Léiomyome (fibrome)</span> — surtout sous-muqueux</li><li><span class=\"kw-alerte\">Malignité / hyperplasie endométriale</span> atypique</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Échographie pelvienne</span> · <span class=\"kw-imagerie\">hystéroscopie diagnostique</span> · <span class=\"kw-bio\">biopsie endométriale</span> (si &gt;<span class=\"kw-chiffre\"> 45 ans</span> ou <span class=\"kw-def\">facteur de risque</span>)</li></ul><h4>CAT</h4><ul><li><span class=\"kw-etio\">Polype</span> → résection <span class=\"kw-ttt\">hystéroscopique</span></li><li><span class=\"kw-etio\">Fibrome / adénomyose</span> → <span class=\"kw-ttt\">DIU LNG</span> 1ʳᵉ intention, <span class=\"kw-ttt\">chirurgie</span> sinon</li><li><span class=\"kw-alerte\">Hyperplasie atypique / cancer</span> → orientation oncologique</li></ul>"},{"id":"t-coein","kind":"terminal","label":"Cause fonctionnelle / iatrogène COEIN","color":"green","detail":"<h4>Étiologies COEIN</h4><ul><li><span class=\"kw-etio\">Coagulopathie</span> — <span class=\"kw-etio\">maladie de Willebrand</span> +++ chez l'adolescente</li><li><span class=\"kw-etio\">Dysfonction ovulatoire</span> (anovulation : SOPK, périménopause, péri-ménarche)</li><li><span class=\"kw-etio\">Iatrogène</span> : <span class=\"kw-ttt\">DIU cuivre</span>, <span class=\"kw-ttt\">microprogestatifs</span>, <span class=\"kw-ttt\">anticoagulants</span></li><li><span class=\"kw-etio\">Cause endométriale</span> (endométrite)</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Acide tranexamique</span> + <span class=\"kw-ttt\">traitement martial</span> (symptomatique)</li><li>Traitement étiologique : réévaluer contraception, <span class=\"kw-ttt\">progestatifs</span> si anovulation, bilan hémostase (<span class=\"kw-bio\">Willebrand</span>) si adolescente</li></ul>"},{"id":"t-post-menopause","kind":"terminal","label":"Cancer de l'endomètre — à éliminer en priorité","color":"red","detail":"<h4>Principe</h4><ul><li><span class=\"kw-alerte\">Toute métrorragie post-ménopausique = cancer de l'endomètre jusqu'à preuve du contraire</span></li></ul><h4>Paraclinique obligatoire</h4><ul><li><span class=\"kw-imagerie\">Échographie pelvienne endovaginale</span> — épaisseur de l'endomètre</li><li><span class=\"kw-imagerie\">Hystéroscopie diagnostique</span> systématique</li><li><span class=\"kw-bio\">Biopsie endométriale</span> (pipelle ou dirigée sous hystéroscopie)</li></ul><h4>Autres causes</h4><ul><li><span class=\"kw-etio\">Atrophie endométriale</span> (cause bénigne la plus fréquente)</li><li><span class=\"kw-etio\">Polypes, fibromes</span></li><li><span class=\"kw-etio\">Cancer du col</span>, sarcomes</li><li><span class=\"kw-etio\">THM mal équilibré</span></li></ul><h4>Renvoi</h4><ul><li>Item 300 (Tumeur du col et du corps utérin)</li></ul>"}]},"cards":[{"i":"01c9742cd318","n":35,"o":"35-1","u":"Définition","t":"Connaître la définition du syndrome prémenstruel","q":"Qu'est-ce que le trouble dysphorique prémenstruel ?","a":"<p>Le trouble dysphorique prémenstruel est une <strong>forme psychiatrique invalidante</strong> du syndrome prémenstruel (SPM), caractérisée par des syndromes psychiatriques cycliques et un retentissement sur la qualité de vie.</p>"},{"i":"04e27c5eee7e","n":35,"o":"35-1","u":"Définition","t":"Connaître la définition du syndrome prémenstruel","q":"Quels sont les trois grandes catégories de signes cliniques classiquement associés au syndrome prémenstruel (SPM) ?","a":"<ul><li>Les <strong>mastodynies</strong> (douleurs ou tension mammaire).</li><li>Les <strong>signes abdomino-pelviens</strong> (ballonnement abdominal, troubles du transit, prise de poids transitoire).</li><li>Les <strong>signes neuropsychologiques</strong> (céphalées, irritabilité, anxiété, syndrome dépressif).</li></ul>"},{"i":"a39323b21ddc","n":35,"o":"35-1","u":"Définition","t":"Connaître la définition du syndrome prémenstruel","q":"Quelle est la définition du syndrome prémenstruel (SPM) ?","a":"<p>Le syndrome prémenstruel (SPM) est un ensemble de <strong>manifestations bénignes</strong>, physiques et psychologiques, qui apparaissent de façon <strong>cyclique</strong> dans les jours précédant les règles et disparaissent au début ou au cours des menstruations.</p>"},{"i":"c102d61cca86","n":35,"o":"35-1","u":"Définition","t":"Connaître la définition du syndrome prémenstruel","q":"Quelle est la fréquence du syndrome prémenstruel (SPM) chez les femmes en âge de procréer ?","a":"<p>Le syndrome prémenstruel (SPM) est la gêne fonctionnelle la plus fréquemment signalée, touchant <strong>30 à 40 % des femmes</strong> en âge de procréer.</p>"},{"i":"0190190879f4","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Quels sont les examens biologiques supplémentaires à envisager face à des méno-métrorragies ?","a":"<ul><li><strong>NFS-plaquettes et bilan martial</strong> (ferritinémie + CRP) pour évaluer un retentissement et dépister une carence martiale.</li><li><strong>TP/TCA et dosage du facteur Willebrand</strong>, particulièrement chez l'adolescente, ou un bilan d'hémostase complet en cas de suspicion de trouble de l'hémostase (antécédents familiaux, prise d'anticoagulants).</li><li><strong>Groupe-Rh-RAI</strong> en cas de saignement abondant.</li><li>Réalisation/vérification du <strong>FCV ou test HPV</strong> selon l'âge et le dépistage en cours.</li></ul>"},{"i":"1e8d777de47c","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Quel est le premier examen biologique à réaliser systématiquement devant des méno-métrorragies chez toute femme en âge de procréer ?","a":"<p>Devant des méno-métrorragies chez toute femme en âge de procréer, il faut systématiquement réaliser un dosage de la <strong>β-hCG plasmatique</strong> afin d'éliminer ou confirmer une grossesse (notamment une grossesse extra-utérine).</p>"},{"i":"6ad3835dde96","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Quelle est la particularité de la prise en charge d'une métrorragie survenant après la ménopause ?","a":"<p>Toute métrorragie survenant <strong>après la ménopause</strong> est considérée comme suspecte et impose systématiquement la réalisation d'une <strong>hystéroscopie avec biopsie endométriale</strong>. En effet, toute métrorragie post-ménopausique doit être considérée comme un <strong>cancer de l'endomètre jusqu'à preuve du contraire</strong>.</p>"},{"i":"cc9d66e30f28","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Quel est l'examen d'imagerie de première intention à réaliser devant des méno-métrorragies et quels éléments permet-il d'évaluer ?","a":"<p>L'examen d'imagerie de première intention est l'<strong>échographie pelvienne sus-pubienne et endovaginale</strong>. Elle permet d'évaluer :</p><ul><li>L'épaisseur de l'endomètre.</li><li>La présence de fibromes (nombre, localisation, taille).</li><li>La présence de polypes.</li><li>L'aspect des ovaires et d'éventuelles masses annexielles.</li><li>Des signes de grossesse intra-utérine ou extra-utérine.</li></ul>"},{"i":"f893eb9bd2fd","n":35,"o":"35-12","u":"Examens complémentaires","t":"Connaître le bilan à réaliser devant des saignements utérins (méno-métrorragies)","q":"Dans quelles situations doit-on envisager une hystéroscopie diagnostique et une biopsie endométriale comme examen de deuxième intention face à des méno-métrorragies ?","a":"<ul><li>Une <strong>hystéroscopie diagnostique</strong> est indiquée en cas de suspicion de pathologie endo-utérine (polype, fibrome sous-muqueux, hyperplasie, cancer) ou systématiquement en cas de <strong>métrorragies post-ménopausiques</strong> avec un endomètre > 4-5 mm à l'échographie.</li><li>Une <strong>biopsie endométriale</strong> est indiquée chez toute patiente de <strong>plus de 45 ans</strong> ou en cas de <strong>facteur de risque de cancer</strong> de l'endomètre. Toute métrorragie post-ménopausique impose l'hystéroscopie avec biopsie endométriale, car c'est un cancer de l'endomètre jusqu'à preuve du contraire.</li></ul>"},{"i":"36f8ef32570b","n":35,"o":"35-4","u":"Définition","t":"Connaître la définition du cycle menstruel normal","q":"Quelle est la méthode de comptage de la durée d'un cycle menstruel normal ?","a":"<p>La durée d'un cycle menstruel normal se compte du <strong>1<sup>er</sup> jour des règles</strong> jusqu'au <strong>1<sup>er</sup> jour des règles suivantes</strong>.</p>"},{"i":"3ad71ff15d09","n":35,"o":"35-4","u":"Définition","t":"Connaître la définition du cycle menstruel normal","q":"Quelles sont les caractéristiques des menstruations considérées comme normales ?","a":"<p>Les menstruations normales durent <strong>3 à 6 jours</strong> et correspondent à des pertes sanguines <strong>inférieures à 80 mL</strong>.</p>"},{"i":"413019f0ec39","n":35,"o":"35-4","u":"Définition","t":"Connaître la définition du cycle menstruel normal","q":"Comment définit-on un cycle menstruel normal ?","a":"<p>Un cycle menstruel normal est un <strong>cycle ovulatoire</strong> dont la durée varie typiquement entre <strong>25 et 35 jours</strong>.</p>"},{"i":"9c541aa62fca","n":35,"o":"35-4","u":"Définition","t":"Connaître la définition du cycle menstruel normal","q":"Que signifie la présence de règles régulières concernant le fonctionnement de l'axe et des voies génitales ?","a":"<p>La présence de règles régulières signe le <strong>bon fonctionnement de l'axe hypothalamo-hypophyso-ovarien</strong> et l'<strong>intégrité des voies génitales</strong>.</p>"},{"i":"58c8412c6391","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelle est la définition des métrorragies et la première démarche diagnostique à adopter chez une femme en âge de procréer ?","a":"<p>Les métrorragies sont des saignements d'origine utérine survenant en dehors des règles.</p><p>Chez une femme en âge de procréer, <strong>toute métrorragie impose d'éliminer en premier lieu une grossesse</strong> (dosage des <strong>β-hCG plasmatiques</strong>), et de ne pas méconnaître une <strong>grossesse extra-utérine (GEU)</strong> tant que la grossesse n'a pas été localisée par échographie.</p>"},{"i":"7f57638d8150","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelles sont les causes iatrogènes ou liées à la contraception pouvant entraîner des métrorragies ?","a":"<ul><li><strong>Contraception œstro-progestative (COP) mal observée</strong> ou en début de plaquette, oublis</li><li><strong>Microprogestatifs</strong>, implant à l'étonogestrel, DIU au lévonorgestrel (spottings fréquents les 1ers mois)</li><li>DIU au cuivre (règles plus abondantes ± spottings)</li><li>Contraception d'urgence</li><li>Traitement hormonal substitutif de la ménopause (THM) mal équilibré</li></ul>"},{"i":"9e19d1a2d1e5","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelles sont les étiologies 'liées à une grossesse' de métrorragies chez la femme en âge de procréer ?","a":"<ul><li><strong>Grossesse extra-utérine (GEU) +++</strong></li><li>Fausse couche spontanée</li><li>Môle hydatiforme</li><li>Grossesse intra-utérine évolutive avec <strong>hémorragie de Hartmann</strong> (J20-J25)</li><li>Pathologies du 2ème-3ème trimestre : <strong>placenta prævia</strong>, <strong>hématome rétroplacentaire</strong></li></ul>"},{"i":"ba9a634b00ba","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelle est la conduite à tenir face à une métrorragie post-ménopausique ?","a":"<p>Toute métrorragie post-ménopausique doit faire considérer un <strong>cancer de l'endomètre jusqu'à preuve du contraire</strong>.</p><p>Le bilan obligatoire comprend une <strong>échographie pelvienne endovaginale</strong> et une <strong>hystéroscopie</strong> (avec ou sans biopsie endométriale).</p>"},{"i":"d2f458ce6f8f","n":35,"o":"35-6","u":"Étiologies","t":"Connaître les principales causes de métrorragies","q":"Quelles sont les principales causes organiques de métrorragies chez la femme en âge de procréer ?","a":"<ul><li><strong>Polypes endométriaux ou cervicaux</strong></li><li><strong>Fibromes utérins</strong> (surtout sous-muqueux)</li><li><strong>Adénomyose</strong></li><li>Endométrite aiguë/chronique, cervicite, IGH</li><li><strong>Cancer du col utérin</strong> (+ chez la femme jeune avec métrorragies provoquées post-coïtales)</li><li>Cancer de l'endomètre (plus rare avant 40 ans)</li></ul>"}]};